@page "/recipes"
@inject RecipeShare.Services.RecipeService RecipeService

<PageTitle>All Categories</PageTitle>

<h1>Recipe Categories</h1>
<ul class="list-group">
    @foreach (var category in RecipeService.GetCategories())
    {
        <li class="list-group-item">
            <a href="recipes/@category">@category</a>
        </li>
    }
</ul>

@page "/recipes/{Category}"
@inject RecipeShare.Services.RecipeService RecipeService

<PageTitle>@Category Recipes</PageTitle>

<h1>@Category Recipes</h1>

<nav aria-label="breadcrumb">
    <ol class="breadcrumb">
        <li class="breadcrumb-item"><a href="recipes">All Categories</a></li>
        <li class="breadcrumb-item active">@Category</li>
    </ol>
</nav>

@if (recipes.Count == 0)
{
    <p>No recipes found in this category.</p>
}
else
{
    <div class="row">
        @foreach (var recipe in recipes)
        {
            <div class="col-md-6 mb-3">
                <div class="card">
                    <div class="card-body">
                        <h5 class="card-title">@recipe.Title</h5>
                        <p class="card-text text-muted">
                            @if (recipe.Ratings.Count > 0)
                            {
                                <span>⭐ @recipe.AverageRating.ToString("F1") (@recipe.Ratings.Count ratings)</span>
                            }
                            else
                            {
                                <span>No ratings yet</span>
                            }
                        </p>
                        <a href="recipes/detail/@recipe.Id" class="btn btn-outline-primary">View Recipe</a>
                    </div>
                </div>
            </div>
        }
    </div>
}

@code {
    [Parameter]
    public string Category { get; set; } = string.Empty;

    private IReadOnlyList<RecipeShare.Models.Recipe> recipes = [];

    protected override void OnParametersSet()
    {
        recipes = RecipeService.GetByCategory(Category);
    }
}

@page "/recipes/detail/{Id:int}"
@inject RecipeShare.Services.RecipeService RecipeService

<PageTitle>@(recipe?.Title ?? "Recipe")</PageTitle>

@if (recipe is null)
{
    <h1>Recipe Not Found</h1>
    <p>The recipe you're looking for doesn't exist.</p>
}
else
{
    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="recipes">All Categories</a></li>
            <li class="breadcrumb-item"><a href="recipes/@recipe.Category">@recipe.Category</a></li>
            <li class="breadcrumb-item active">@recipe.Title</li>
        </ol>
    </nav>

    <h1>@recipe.Title</h1>
    <span class="badge bg-secondary mb-3">@recipe.Category</span>

    <h3>Ingredients</h3>
    <ul class="list-group mb-3">
        @foreach (var ingredient in recipe.Ingredients.Split('\n', StringSplitOptions.RemoveEmptyEntries))
        {
            <li class="list-group-item">@ingredient</li>
        }
    </ul>

    <h3>Steps</h3>
    <ol class="list-group list-group-numbered mb-4">
        @foreach (var step in recipe.Steps.Split('\n', StringSplitOptions.RemoveEmptyEntries))
        {
            var text = System.Text.RegularExpressions.Regex.Replace(step, @"^\d+\.\s*", "");
            <li class="list-group-item">@text</li>
        }
    </ol>

    <StarRating RecipeId="recipe.Id" CurrentRating="recipe.AverageRating" RatingCount="recipe.Ratings.Count" />
}

@code {
    [Parameter]
    public int Id { get; set; }

    private RecipeShare.Models.Recipe? recipe;

    protected override void OnParametersSet()
    {
        recipe = RecipeService.GetById(Id);
    }
}

@rendermode InteractiveServer
@inject RecipeShare.Services.RecipeService RecipeService

<div class="my-3 p-3 border rounded">
    <h4>Rate this Recipe</h4>
    <p class="text-muted">
        @if (RatingCount > 0)
        {
            <span>Current rating: @CurrentRating.ToString("F1") ⭐ (@RatingCount ratings)</span>
        }
        else
        {
            <span>No ratings yet — be the first!</span>
        }
    </p>
    <div class="d-flex gap-1 mb-2">
        @for (int i = 1; i <= 5; i++)
        {
            var star = i;
            <button class="btn btn-lg p-0 border-0 @(star <= selectedRating ? "text-warning" : "text-secondary")"
                    @onclick="() => Rate(star)"
                    title="@star star(s)"
                    style="font-size: 2rem; cursor: pointer; background: none;">
                @(star <= selectedRating ? "★" : "☆")
            </button>
        }
    </div>
    @if (submitted)
    {
        <div class="alert alert-success mt-2">Thanks for rating! You gave @selectedRating star(s).</div>
    }
</div>

@code {
    [Parameter]
    public int RecipeId { get; set; }

    [Parameter]
    public double CurrentRating { get; set; }

    [Parameter]
    public int RatingCount { get; set; }

    private int selectedRating;
    private bool submitted;

    private void Rate(int stars)
    {
        selectedRating = stars;
        RecipeService.AddRating(RecipeId, stars);
        var recipe = RecipeService.GetById(RecipeId);
        if (recipe is not null)
        {
            CurrentRating = recipe.AverageRating;
            RatingCount = recipe.Ratings.Count;
        }
        submitted = true;
    }
}

@page "/submit"
@rendermode InteractiveServer
@inject RecipeShare.Services.RecipeService RecipeService

<PageTitle>Submit a Recipe</PageTitle>

<h1>Submit a Recipe</h1>
<p>Share your favorite recipe with the community.</p>

@if (submitted)
{
    <div class="alert alert-success">
        <strong>Recipe submitted!</strong> "@title" has been added to the @category category.
    </div>
    <a href="recipes/@category" class="btn btn-primary">View in @category</a>
}
else
{
    <EditForm Model="this" OnValidSubmit="HandleSubmit" FormName="submitRecipe">
        <div class="mb-3">
            <label for="title" class="form-label">Recipe Title</label>
            <InputText id="title" class="form-control" @bind-Value="title" placeholder="e.g., Grandma's Apple Pie" />
        </div>

        <div class="mb-3">
            <label for="category" class="form-label">Category</label>
            <InputSelect id="category" class="form-select" @bind-Value="category">
                <option value="">-- Select a category --</option>
                @foreach (var cat in RecipeService.GetCategories())
                {
                    <option value="@cat">@cat</option>
                }
                <option value="Other">Other</option>
            </InputSelect>
        </div>

        <div class="mb-3">
            <label for="ingredients" class="form-label">Ingredients (one per line)</label>
            <InputTextArea id="ingredients" class="form-control" @bind-Value="ingredients" rows="6"
                placeholder="2 cups flour&#10;1 cup sugar&#10;3 apples, sliced" />
        </div>

        <div class="mb-3">
            <label for="steps" class="form-label">Steps (one per line)</label>
            <InputTextArea id="steps" class="form-control" @bind-Value="steps" rows="6"
                placeholder="Preheat oven to 350°F&#10;Mix dry ingredients&#10;Add wet ingredients" />
        </div>

        <button type="submit" class="btn btn-success"
                disabled="@(string.IsNullOrWhiteSpace(title) || string.IsNullOrWhiteSpace(category) || string.IsNullOrWhiteSpace(ingredients) || string.IsNullOrWhiteSpace(steps))">
            Submit Recipe
        </button>
    </EditForm>
}

@code {
    private string title = string.Empty;
    private string category = string.Empty;
    private string ingredients = string.Empty;
    private string steps = string.Empty;
    private bool submitted;

    private void HandleSubmit()
    {
        if (string.IsNullOrWhiteSpace(title) || string.IsNullOrWhiteSpace(category)
            || string.IsNullOrWhiteSpace(ingredients) || string.IsNullOrWhiteSpace(steps))
            return;

        RecipeService.AddRecipe(new RecipeShare.Models.Recipe
        {
            Title = title,
            Category = category,
            Ingredients = ingredients,
            Steps = steps
        });

        submitted = true;
    }
}

